// MESA CLUB 9.0 · seis juegos 1v1 y tutorial jugable Air Hockey contra bot fácil.
'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),zlib=require('node:zlib');
const payload="";
const bytes=Buffer.from(payload,'base64');
if(crypto.createHash('sha256').update(bytes).digest('hex')!=="1fb6cbb779c5add5cf6879f2dc6854b5be9a31269703a6db29c78be2a9437eac")throw Error('Archivo MESA CLUB 9 corrupto');
const contents=JSON.parse(zlib.brotliDecompressSync(bytes).toString('utf8'));
for(const [name,source] of Object.entries(contents)){
 if(!/^(server|chess|store|domino|pool|arcade|backup|migrate)\.js$|^public\/(index\.html|app\.js|styles\.css|tutorial\.js)$/.test(name))throw Error('Ruta de código no autorizada');
 const out=path.join(__dirname,name);fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,source,'utf8');
}
console.log('MESA CLUB 9 preparado: tutorial de Air Hockey VS bot fácil.');
const {server}=require('./server');
const {init,getStorage,shutdown}=require('./store');
init().then(()=>server.listen(Number(process.env.PORT)||3000,'0.0.0.0',()=>console.log('MESA CLUB 9 online · almacenamiento: '+getStorage())))
.catch(err=>{console.error('Error iniciando MESA CLUB 9:',err.message);process.exitCode=1;shutdown().catch(()=>{});server.close();});
